const fs=require('fs'),p=require('path'),c=require('crypto'),r=process.argv[2],rd=n=>JSON.parse(fs.readFileSync(p.join(r,n),'utf8').replace(/^\uFEFF/,'')),sh=x=>c.createHash('sha256').update(x).digest('hex');const d=rd('Index_trasabilitate.json'),cs=new Map(d.controls.map(x=>[x.id,x])),ps=new Map(d.pipelines.map(x=>[x.id,x])),ts=new Map(d.tasks.map(x=>[x.ref,x])),as=rd('A12_index_taskuri.json');console.log('INDEX',cs.size,ps.size,ts.size);let broken=[],oneWay=[],missing=[],tasks=new Set();for(const ctrl of cs.values()){const [n,q]=ctrl.plan_ref.split('#/'),parts=q.split('/');let found=rd(n);for(const part of parts){found=found?.[part]}if(!found||!(found.control_id===ctrl.id||found.id===ctrl.id))broken.push(['bad pointer',ctrl.id,ctrl.plan_ref]);for(const pp of ctrl.planned_pipelines){if(!ps.has(pp))broken.push(['unknown pipeline',ctrl.id,pp]);else if(!ps.get(pp).declared_control_ids.includes(ctrl.id))oneWay.push([ctrl.id,pp])}for(const id of ctrl.explicit_tasks){let t=ts.get(id)||d.tasks.find(x=>x.canonical===id);if(!t)broken.push(['unknown task',ctrl.id,id]);else{tasks.add(t.ref);if(!t.explicit_controls.includes(ctrl.id))oneWay.push(['taskrev',ctrl.id,id])}}}for(let f of rd('Plan_director.json').zones){if(!f.available||sh(fs.readFileSync(p.join(r,f.file)))!==f.hash)broken.push(['director/hash',f.id])}
