let tech=rd('Verificare_corpus.json'),mp=new Map(tech.case_collisions.map(x=>[x.repo_path,x.read_from]));let src=p.dirname(tech.source_manifest),m=JSON.parse(fs.readFileSync(tech.source_manifest,'utf8')),dm=JSON.parse(fs.readFileSync(p.join(src,'DOCS_MANIFEST.json'),'utf8'));console.log('docs',Object.keys(dm));let err=[];for (const f of [...m.files,...(dm.files||[])]){let fn=mp.get(f.path)||p.join(src,f.path),z=fs.readFileSync(fn);if(z.length!==f.bytes||sh(z)!==f.sha256||c.createHash('sha1').update(Buffer.from('blob '+z.length+'\0')).update(z).digest('hex')!==f.oid)err.push(f.path)}console.log('CORPUS mismatch',err.length);
